18	package com.adobe.acs.commons.mcp.form;
19	
20	import java.io.IOException;
21	import java.io.PrintWriter;
22	import java.util.Arrays;
23	import java.util.HashSet;
24	import java.util.Set;
25	import java.util.logging.Level;
26	import java.util.logging.Logger;
27	import javax.annotation.processing.AbstractProcessor;
28	import javax.annotation.processing.RoundEnvironment;
29	import javax.lang.model.SourceVersion;
30	import javax.lang.model.element.Element;
31	import javax.lang.model.element.TypeElement;
32	import javax.tools.JavaFileObject;
33	import org.apache.commons.lang.StringUtils;
34	import org.apache.sling.models.annotations.Model;
35	
36	/**
37	 * Processes the DialogProvider annotation, producing a corresponding OSGi
38	 * service to provide the generated sling dialog resources. This annotation
39	 * processor will skip any classes which do not identify their corresponding
40	 * sling model either as part of the model annotation or by a property or getter
41	 * method.
42	 */
43	public class DialogProviderAnnotationProcessor extends AbstractProcessor {
44	
45	    private static final Logger LOG = Logger.getLogger(DialogProviderAnnotationProcessor.class.getName());
46	
47	    @Override
48	    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
49	        for (Element annotatedElement : roundEnv.getElementsAnnotatedWith(DialogProvider.class)) {
50	            try {
51	                processDialogProviderAnnotation(annotatedElement);
52	            } catch (IOException ex) {
53	                LOG.log(Level.SEVERE, null, ex);
54	                return false;
55	            }
56	        }
57	        return true;
58	    }
59	
60	    @Override
61	    public Set<String> getSupportedAnnotationTypes() {
62	        return new HashSet<>(Arrays.asList(DialogProvider.class.getCanonicalName()));
63	    }
64	
65	    @Override
66	    public SourceVersion getSupportedSourceVersion() {
67	        return SourceVersion.RELEASE_8;
68	    }
69	
70	    private void processDialogProviderAnnotation(Element element) throws IOException {
71	        TypeElement t = (TypeElement) element;
72	        String className = t.getQualifiedName().toString();
73	        String serviceClassName = DialogResourceProvider.getServiceClassName(className);
74	        if (providesResourceType(t)) {
75	            if (LOG.isLoggable(Level.INFO)) {
76	                LOG.log(Level.INFO, String.format("Generated resource provider service for class %s => %s", className, serviceClassName));
77	            }
78	            JavaFileObject builderFile = processingEnv.getFiler().createSourceFile(serviceClassName);
79	            writeServiceStub(builderFile, serviceClassName, className);
80	        } else {
81	            if (LOG.isLoggable(Level.WARNING)) {
82	                LOG.log(Level.WARNING, String.format("Class %s declares or inherits the DialogProvider annotation but does not declare a resource type -- no resource provider generated.", className));
83	            }
84	        }
85	    }
86	
87	    private void writeServiceStub(JavaFileObject builderFile, String serviceClass, String targetClass) throws IOException {
88	        try (PrintWriter out = new PrintWriter(builderFile.openWriter())) {
89	            String packageName = StringUtils.substringBeforeLast(serviceClass, ".");
90	            String className = StringUtils.substringAfterLast(serviceClass, ".");
91	            String osgiService = DialogResourceProvider.class.getCanonicalName();
92	            out.println(String.format("package %s;", packageName));
93	            out.println();
94	            out.println("import javax.annotation.Generated;");
95	            out.println("import org.osgi.annotation.versioning.ConsumerType;");
96	            out.println("import org.osgi.framework.BundleContext;");
97	            out.println("import org.osgi.service.component.annotations.*;");
98	            out.println();
99	            out.println("@Generated(\"Created by the ACS Commons DialogProviderAnnotationProcessor\")");
100	            out.println("@ConsumerType");
101	            out.println(String.format("@Component(service = %s.class, immediate = true)", osgiService));
102	            out.println(String.format("public class %s implements %s {", className, osgiService));
103	            out.println();
104	            out.println(String.format("    @Override%n    public Class getTargetClass() {%n        return %s.class;%n    }", targetClass));
105	            out.println("    @Activate\n    public void activate(BundleContext context) throws InstantiationException, IllegalAccessException, ReflectiveOperationException {\n        this.doActivate(context);\n    }\n");
106	            out.println("    @Deactivate\n    public void deactivate(BundleContext context) {\n        this.doDeactivate();\n    }");
107	            out.println("}");
108	            out.flush();
109	        }
110	    }
111	
112	    private boolean providesResourceType(TypeElement t) {
113	        Model model = t.getAnnotation(Model.class);
114	        if (model != null && model.resourceType() != null && model.resourceType().length > 0) {
115	            return true;
116	        } else {
117	            return t.getEnclosedElements().stream().anyMatch(this::elementProvidesResourceType);
118	        }
119	    }
120	
121	    private boolean elementProvidesResourceType(Element t) {
122	        switch (t.getKind()) {
123	            case LOCAL_VARIABLE:
124	            case FIELD:
125	                return t.getSimpleName().contentEquals("resourceType");
126	            case METHOD:
127	                return t.getSimpleName().contentEquals("getResourceType");
128	            default:
129	                return false;
130	        }
131	    }
132	}
